const item = $input.first();
const body = item.json.body || item.json;

if (body.event !== 'message_created') return [];
if (body.message_type !== 'incoming') return [];
if (body.sender && (body.sender.type === 'user' || body.sender.type === 'agent_bot')) return [];
if (body.content_attributes && Object.keys(body.content_attributes).length > 0) return [];

// Obtener historial de mensajes anteriores de la conversación
let historial = [];
try {
  const convData = await this.helpers.httpRequest({
    method: 'GET',
    url: `http://127.0.0.1:3000/api/v1/accounts/${body.account.id}/conversations/${body.conversation.id}/messages`,
    headers: {
      'api_access_token': 'TU_CHATWOOT_ACCESS_TOKEN'
    },
    json: true
  });

  // Convertir historial al formato de mensajes para Groq
  const mensajes = (convData.payload || []).slice(-6); // últimos 6 mensajes
  historial = mensajes
    .filter(m => m.content && m.content.trim())
    .map(m => ({
      role: m.message_type === 0 ? 'user' : 'assistant',
      content: m.content
    }));
} catch(e) {
  historial = [];
}

// Si ya hay historial, Sara ya saludó — no debe volver a hacerlo
const yaSaludo = historial.length > 1;

return [{
  json: {
    conversation_id: body.conversation.id,
    account_id: body.account.id,
    sender_nombre: body.sender ? body.sender.name : 'Cliente',
    texto_mensaje: body.content || '',
    historial: historial,
    prompt_sistema: `Eres Sara, la asistente virtual de Entre Ágiles, empresa colombiana de capacitación y certificaciones TI. Tienes una personalidad cálida, amable y cercana siempre saluda con buenos dias, buenas tardes o buenas noches.

TONO Y ESTILO:
- Escribe como una persona real, no como un robot
- Usa lenguaje natural y cercano, apropiado para Colombia
- Puedes usar expresiones como "claro que sí", "con gusto"
- Usa emojis con moderación — uno o dos por mensaje máximo
- Si alguien pregunta cómo estás, responde de forma genuina y amable
- Si no sabes algo, pásalo a un asesor sin que se note

${yaSaludo ? 
'YA SALUDASTE ANTES — No repitas "Hola" ni ningún saludo. Ve directo al punto de la conversación.' : 
'PRIMER CONTACTO — Saluda con calidez y pregunta en qué puedes ayudar.'}

CUANDO EL CLIENTE TIENE UN PROBLEMA:
Pide amablemente estos datos:
- Nombre completo
- Número de cédula
- Correo electrónico

LINKS ÚTILES:
- Grabaciones, sesiones, plataforma de examen o grupo de WhatsApp → https://comunidad.entreagiles.com/public/my-sessions

SOBRE ENTRE ÁGILES:
- Certificaciones: ITIL 4, Scrum, PMP, COBIT, AWS, Azure, CompTIA
- Vouchers Pearson VUE y CertMind
- Plataforma: app.entreagiles.com
- Clases por Teams y Zoom

PROCESO DE EXÁMENES:
1. Compras el voucher con Entre Ágiles
2. Lo activas en CertMind o Pearson VUE
3. Agendas tu examen en el portal
4. Presencial o desde casa (online proctored)

PUEDES RESPONDER: proceso de examen, vouchers, CertMind vs Pearson, requisitos online, certificaciones, acceso a plataforma.

PASA AL ASESOR SI: pide hablar con persona, necesita info de su cuenta/pago/examen específico.

Responde SIEMPRE en JSON válido:
{"puede_resolver": true/false, "necesita_humano": true/false, "categoria": "examenes|plataforma|tecnico|general", "respuesta": "mensaje para el cliente", "razon": "solo si necesita_humano"}`
  }
}];

const item = $input.first();

// Limpiar historial — eliminar vacíos y asegurar que empiece con user
let historialLimpio = (item.json.historial || []).filter(m => 
  m.content && m.content.trim() !== '' && m.content !== null
);

// Groq requiere que el primer mensaje sea siempre role: user
// Si empieza con assistant, lo eliminamos
if (historialLimpio.length > 0 && historialLimpio[0].role === 'assistant') {
  historialLimpio = historialLimpio.slice(1);
}

// Verificar que no haya dos mensajes consecutivos del mismo rol
const historialFinal = [];
for (let i = 0; i < historialLimpio.length; i++) {
  if (i === 0 || historialLimpio[i].role !== historialLimpio[i-1].role) {
    historialFinal.push(historialLimpio[i]);
  }
}

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.groq.com/openai/v1/chat/completions',
  headers: {
    'Authorization': 'Bearer TU_GROQ_API_KEY',
    'Content-Type': 'application/json'
  },
  body: {
    model: 'openai/gpt-oss-20b',
    temperature: 0.4,
    max_tokens: 1024,
    messages: [
      {role: 'system', content: item.json.prompt_sistema},
      ...historialFinal,
      {role: 'user', content: item.json.sender_nombre + ': ' + item.json.texto_mensaje}
    ]
  },
  json: true
});

return [{
  json: {
    ...response,
    conversation_id: item.json.conversation_id,
    account_id: item.json.account_id,
    sender_nombre: item.json.sender_nombre,
    texto_mensaje: item.json.texto_mensaje
  }
}];

const item = $input.first();
const content = item.json.choices[0].message.content;

let parsed;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch(e) {
  parsed = {puede_resolver: false, necesita_humano: true, categoria: 'general', respuesta: 'Un momento, te conectamos con un especialista de Entre Ágiles.', razon: 'Error IA'};
}

const mensaje = (item.json.texto_mensaje || '').toLowerCase();
const pideHumano = mensaje.includes('asesor') || mensaje.includes('humano') || mensaje.includes('hablar con') || mensaje.includes('agente') || mensaje.includes('persona');

if (parsed.respuesta && parsed.respuesta.length > 20 && !pideHumano) {
  parsed.puede_resolver = true;
  parsed.necesita_humano = false;
}

if (pideHumano) {
  parsed.puede_resolver = false;
  parsed.necesita_humano = true;
  parsed.razon = 'Cliente solicitó hablar con un asesor';
}

return [{json: {
  ...parsed,
  conversation_id: item.json.conversation_id,
  account_id: item.json.account_id,
  sender_nombre: item.json.sender_nombre,
  texto_mensaje: item.json.texto_mensaje
}}];

const item = $input.all()[0];
const now = new Date();
const col = new Date(now.toLocaleString('en-US',{timeZone:'America/Bogota'}));
const hora = col.getHours() + col.getMinutes()/60;
const dia = col.getDay();
return [{json:{...item.json, hora_colombia:hora, dia_semana:dia, hora_formato:col.toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit'})}}];

const item = $input.all()[0];
const hora = item.json.hora_colombia;
const dia = item.json.dia_semana;
const categoria = item.json.categoria;

// Chatwoot Agent IDs
// ⚠️ Angel aún no está en Chatwoot — usando ID 2 (Soporte) como placeholder
// Cuando agregues a Angel, reemplaza 2 con su ID real
const asesores = [
  {
    id: 1, chatwoot_id: 2, nombre: 'Angel David Garzón', especialidad: 'general',
    horario: {1:[{i:8,f:12},{i:13,f:16.5}],2:[{i:8,f:12},{i:13,f:16.5}],3:[{i:8,f:12},{i:13,f:16.5}],4:[{i:8,f:12}],5:[{i:8,f:12},{i:13,f:16.5}],6:[{i:8,f:12}]}
  },
  {
    id: 2, chatwoot_id: 3, nombre: 'Edwar Ortiz Melo', especialidad: 'general',
    horario: {1:[{i:13,f:21}],2:[{i:13,f:21}],3:[{i:13,f:21}],4:[{i:13,f:21}],5:[{i:9,f:13},{i:14,f:17.5}],6:[{i:8,f:12}]}
  },
  {
    id: 3, chatwoot_id: 4, nombre: 'Stephania Ortiz', especialidad: 'examenes',
    horario: {1:[{i:10,f:20}],2:[{i:10,f:20}],3:[{i:15.5,f:20}],4:[{i:13,f:20}],5:[{i:13,f:14},{i:16.5,f:20}],6:[{i:8,f:12}]}
  }
];

function disponible(a,d,h){
  const t=a.horario[d];
  return t&&t.some(s=>h>=s.i&&h<s.f);
}

let disp=asesores.filter(a=>disponible(a,dia,hora));
if(categoria==='examenes'){
  disp=[...disp.filter(a=>a.especialidad==='examenes'),...disp.filter(a=>a.especialidad!=='examenes')];
}

return [{json:{...item.json,asesores_disponibles:disp,hay_disponibles:disp.length>0}}];

const item = $input.all()[0];
const disponibles = item.json.asesores_disponibles;
return [{json:{
  ...item.json,
  asesor_elegido: disponibles[0],
  account_id: item.json.account_id,
  conversation_id: item.json.conversation_id
}}];
